static VbNativeFn vb_native_lookup(uint32_t pc) {
    unsigned lo=0, hi=sizeof(vb_routes)/sizeof(vb_routes[0]);
    while (lo < hi) { unsigned mid=lo+(hi-lo)/2; if(vb_routes[mid].pc < pc) lo=mid+1; else hi=mid; }
    return lo < sizeof(vb_routes)/sizeof(vb_routes[0]) && vb_routes[lo].pc == pc ? vb_routes[lo].fn : 0;
}
static void vb_dispatch_loop(CPUState* cpu, uint64_t saved_lp) {
    /* NOTE: do NOT clear cpu->yielded here — the main
     * loop clears it before the top-level vb_dispatch. A
     * recursive vb_dispatch_call from inside a yielded
     * stack must preserve the flag so the unwind can
     * bubble it back to the top. */
    while (cpu->pc != saved_lp && !cpu->halted && !cpu->yielded) {
        uint32_t pc = cpu->pc;
        if (vb_execution.mode == VB_EXEC_INTERPRETER) {
            if (!cpu->step_budget || cpu->cycles >= cpu->cycle_deadline) { cpu->yielded = 1; return; }
            --cpu->step_budget; vb_interpreter_step(cpu); continue;
        }
        VbNativeFn native = vb_native_lookup(pc);
        if (native) { ++vb_execution.native_entries; native(cpu); }
        else { vb_interpreter_fallback(cpu); }
    }
}

void vb_dispatch_call(CPUState* cpu, uint32_t target_pc, uint32_t lp) {
    /* JAL semantic: writeback the link register and enter
     * the dispatch loop with the JAL's fall-through PC as
     * the saved_lp gate. The callee's eventual JMP r31
     * returns control here when cpu->pc == lp. */
    cpu->gpr[31] = lp;
    cpu->pc = target_pc;
    vb_dispatch_loop(cpu, lp);
}

void vb_dispatch(CPUState* cpu, uint32_t target_pc) {
    /* Preserve the live link register on initial entry and resume. */
    cpu->pc = target_pc;
    vb_dispatch_loop(cpu, VB_TOP_LEVEL_LP);
}

/* CRC32 of the ROM this recompiler run was generated from.
 * main.cpp computes the CRC32 of the file it loads and compares;
 * a mismatch means the user provided a different cart than the
 * one this binary was built for. */
uint32_t vb_game_expected_crc32(void) { return 0x7CE7460Du; }